372	/** Settles each selected claim, in list order: its people by their positions, a person's
373	 *  claims newest first. Each goes through the very steps of a single settle by the user (period,
374	 *  clerk limit, opened-by, edited-by and status checks, then store, log and audit), so a clerk's settle above
375	 *  the clerk limit sends it to PENDING, which counts as settled. A claim that is not on the sheet,
376	 *  or that a single settle would refuse (every claim on an archived sheet), is refused.
377	 *  All or nothing: when any is refused, none is settled, every one counts as refused and nothing is
378	 *  stored or audited. Otherwise the bulk settle takes the sheet's next batch, each settled claim records
379	 *  it, and after the claims' own records BATCH_SETTLED sheet=<id> by=<user> batch=<n> count=<claims>
380	 *  total=<the frozen figures of those SETTLED, added up> is written. */
381	public class SettleClaims {
382	    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleInput input, ClaimStore store,
383	            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles,
384	            RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, WatchStore watches,
385	            VoidReasonStore voidReasons, PlatformTransactionManager transactions,
386	            Out<BulkSettleResult> result) {
387	        String sheet = sheetId.trim();
388	        Map<Long, Integer> personOrder = new HashMap<>();
389	        // A person's claims newest first, as listed: a claim moved to them is listed as their newest.
390	        Map<Long, Integer> listed = new HashMap<>();
391	        for (Claim claim : store.list(sheet)) {
392	            listed.put(claim.getId(), listed.size());
393	        }
394	        for (Person person : people.list(sheet)) {
395	            personOrder.put(person.getId(), personOrder.size());
396	        }
397	        int refused = 0;
398	        List<Claim> selected = new ArrayList<>();
399	        for (Long id : input.claimIds()) {
400	            Claim claim = id == null ? null : store.find(sheet, id);
401	            if (claim == null) {
402	                refused++;
403	            } else {
404	                selected.add(claim);
405	            }
406	        }
407	        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
408	                .thenComparing(c -> listed.getOrDefault(c.getId(), Integer.MAX_VALUE)));
409	        StatusInput status = new StatusInput(ClaimStatus.SETTLED, input.user(), false, "");
410	        int all = input.claimIds().size();
411	        if (refused > 0) {
412	            result.set(new BulkSettleResult(0, all));
413	            return;
414	        }
415	        // All or nothing: the claims are settled in a nested transaction, their audit records held back,
416	        // and the first refusal rolls every one of them back and drops the records.
417	        TransactionTemplate nested = new TransactionTemplate(transactions);
418	        nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
419	        audit.hold();
420	        boolean done = false;
421	        try {
422	            done = Boolean.TRUE.equals(nested.execute(tx -> {
423	                long batch = store.nextBatch(sheet);
424	                BigDecimal total = BigDecimal.ZERO;
425	                for (Claim claim : selected) {
426	                    try {
427	                        sheets.refuseArchived(sheet);
428	                        new CheckClaimPeriod().check(claim, periods);
429	                        StatusMove[] move = new StatusMove[1];
430	                        new CheckClerkLimit().check(status, claim, roles, settings, people, rates, sheets, store, log,
431	                                m -> move[0] = m);
432	                        Rollup before = rollups.snapshot(sheet);
433	                        StatusChange[] change = new StatusChange[1];
434	                        new ApplyStatus().apply(status, move[0], claim, store, people, rates, settings, sheets, periods,
435	                                voidReasons, c -> change[0] = c);
436	                        new SaveClaim().save(status, claim, store, log);
437	                        store.markBatch(claim, batch);
438	                        new AuditClaimStatus().audit(status, move[0], claim, change[0], before, people, audit, rollups,
439	                                watches);
440	                        if (move[0].to() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
441	                            total = total.add(claim.getSettledDue());
442	                        }
443	                    } catch (InvalidSheetException e) {
444	                        tx.setRollbackOnly();
445	                        return false;
446	                    }
447	                }
448	                audit.record("BATCH_SETTLED sheet=" + sheet + " by=" + input.user() + " batch=" + batch + " count="
449	                        + selected.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
450	                return true;
451	            }));
452	        } finally {
453	            if (done) {
454	                audit.release();
455	            } else {
456	                audit.discard();
457	            }
458	        }
459	        result.set(done ? new BulkSettleResult(selected.size(), 0) : new BulkSettleResult(0, all));
460	    }
461	}
