=== CheckProofs.java
/** Refuses settling an OPEN claim, or approving a PENDING one, while it has no proofs and its due is above
 *  the proof threshold in force on its date (its person's grade's then when one is set, else the sheet's). A sheet with no threshold then, and a claim whose due is n/a,
 *  need no proof. */
final class CheckProofs {
    private CheckProofs() {
    }
    static void refuseUnproved(StatusInput input, Claim claim, SettingStore settings, PersonStore people,
            RateStore rates, SheetStore sheets, ClaimStore claims) throws InvalidSheetException {
        ClaimStatus from = claim.getStatus();
        if (input.status() != ClaimStatus.SETTLED || (from != ClaimStatus.OPEN && from != ClaimStatus.PENDING)
                || claim.getProofs() > 0) {
            return;
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        String grade = person == null ? null : person.gradeOn(claim.getDate());
        BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), grade, claim.getDate());
        if (threshold == null) {
            return;
        }
        BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), grade, claim.getDate());
        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
        if (due != null && due.compareTo(threshold) > 0) {
            throw new InvalidSheetException("A claim due above the proof threshold of " + threshold.setScale(2)
                    + " needs a proof before it can be " + (input.review() ? "approved" : "settled"));
        }
    }
    /** Refuses opening a DRAFT claim with an empty note while its due is above the note threshold in force on
     *  its date. A sheet with no threshold then, and a claim whose due is n/a, need no note. */
    static void refuseUnnoted(Claim claim, SettingStore settings, PersonStore people, RateStore rates,
            SheetStore sheets, ClaimStore claims) throws InvalidSheetException {
        if (claim.getNote() != null && !claim.getNote().isBlank()) {
            return;
        }
        BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
        if (threshold == null) {
            return;
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
        if (due != null && due.compareTo(threshold) > 0) {
            throw new InvalidSheetException("A claim due above the note threshold of " + threshold.setScale(2)
                    + " needs a note before it can be opened");
        }
    }
}
=== CheckReassign.java
/** Refuses a claim's move unless a role the sheet's permission matrix allows to reassign (by
 *  default a steward) moves a DRAFT, OPEN or PENDING claim that is not a
 *  correction to another person on the sheet, who is not retired from before the claim's date. */
public class CheckReassign {
    public void check(@Val ReassignInput input, @Val Claim claim, RoleStore roles, PersonStore people,
            SettingStore settings, Out<Reassignment> reassignment) throws InvalidSheetException {
        reassignment.set(refuse(input, claim, roles, people, settings, false));
    }
    /** The move, or refused as a single move is; a bulk move lets a claim "move" to the person it is with. */
    static Reassignment refuse(ReassignInput input, Claim claim, RoleStore roles, PersonStore people,
            SettingStore settings, boolean bulk) throws InvalidSheetException {
        Role role = roles.find(claim.getSheetId(), input.user());
        if (!settings.allows(claim.getSheetId(), "reassign", role)) {
            throw new InvalidSheetException("A " + role.shown() + " may not move a claim");
        }
        if (!claim.getStatus().canMove()) {
            throw new InvalidSheetException("A " + claim.getStatus() + " claim cannot move");
        }
        if (claim.isCorrection()) {
            throw new InvalidSheetException("A correction stays with the claim it corrects");
        }
        Person from = people.find(claim.getSheetId(), claim.getPersonId());
        Person to = people.find(claim.getSheetId(), input.to());
        if (to == null) {
            throw new InvalidSheetException("No such person: " + input.to());
        }
        if (!bulk && to.getId() == claim.getPersonId()) {
            throw new InvalidSheetException("The claim is already " + to.getName() + "'s");
        }
        Retirement.refuseClaimDate(to, claim.getDate());
        return new Reassignment(from, to);
    }
}
