/** A person's due-total: the sum of the figures of their claims that count, at most the sheet's cap
 *  (two decimals; null or undefined for none). n/a when their grade
 *  in force on the sheet's today has no rate then, unless a claim that counts keeps a fixed (settled or
 *  stated) figure, or a figure at another grade (the one in force on its date), or at a rate that ended before today;
 *  n/a is not capped. */
export function personDue(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
  cap?: string | null,
): string {
  const total = uncappedDue(claims, rates, grades, today, floor, late);
  return total === NA || cap == null || hundredths(total) <= hundredths(cap) ? total : format(hundredths(cap));
}

/** A person's excess: how far the sum of their figures is above the sheet's cap; 0.00 when it is not, or
 *  there is no cap, or their due-total is n/a. */
export function personExcess(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
  cap?: string | null,
): string {
  const total = uncappedDue(claims, rates, grades, today, floor, late);
  return total === NA || cap == null || hundredths(total) <= hundredths(cap)
    ? format(0n)
    : format(hundredths(total) - hundredths(cap));
}

/** A person's due-total before the cap (see `personDue`). */
function uncappedDue(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
): string {
  const mine = claims.filter(counts);
  const now = gradeOn(grades, today);
  const elsewhere = (c: Claim) => {
    const grade = gradeOn(grades, c.date);
    return rateOf(rates, grade, c.date) !== undefined
      && (grade !== now || (today !== undefined && endsBefore(rates, grade, c.date, today)));
  };
  if (rateOf(rates, now, today) === undefined && !mine.some((c) => fixed(c) || elsewhere(c))) {
    return NA;
  }
  return dueTotal(mine.map((c) => claimDue(c, rates, grades, floor, late)));
}

/** A person's settled-total and open-total: the sum of the dues (skipping n/a) of their claims that count
 *  that are SETTLED (at their frozen figures), and that are OPEN or PENDING. Together they make their
 *  due-total before the cap (0.00 each when it is n/a). */
export function personSplit(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
): { settled: string; open: string } {
  if (uncappedDue(claims, rates, grades, today, floor, late) === NA) return { settled: format(0n), open: format(0n) };
  const mine = claims.filter(counts);
  const total = (keep: (c: Claim) => boolean) =>
    dueTotal(mine.filter(keep).map((c) => claimDue(c, rates, grades, floor, late)));
  return { settled: total((c) => c.status === 'SETTLED'), open: total((c) => c.status !== 'SETTLED') };
}

/** A person's due on a tag: the sum of the dues (skipping n/a) of their claims that count that carry it, or
 *  all of them when the person (whose tags are `personTags`) carries it, each once; 0.00 when their due-total is n/a. */
export function personTagged(
  claims: Claim[],
  tag: string,
  personTags: string[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
): string {
  return personDueWhere(claims, (c) => personTags.includes(tag) || c.tags.includes(tag), rates, grades, today, floor, late);
}

/** A person's due in a calendar month (yyyy-mm): the sum of the dues (skipping n/a) of their claims that
 *  count dated in it; 0.00 when their due-total is n/a. */
export function personMonthDue(
  claims: Claim[],
  month: string,
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
): string {
  return personDueWhere(claims, (c) => c.date.slice(0, 7) === month, rates, grades, today, floor, late);
}

/** The sum of the dues (skipping n/a) of a person's claims that count that `keep` picks; 0.00 when their
 *  due-total is n/a. */
function personDueWhere(
  claims: Claim[],
  keep: (c: Claim) => boolean,
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
): string {
  if (uncappedDue(claims, rates, grades, today, floor, late) === NA) return format(0n);
  return dueTotal(claims.filter((c) => counts(c) && keep(c)).map((c) => claimDue(c, rates, grades, floor, late)));
}

/** A preview of a candidate percent for a grade: of these people's OPEN and PENDING claims whose person
 *  was on the grade on the claim's date, how many would show a different due were the candidate the
 *  grade's only rate (from the beginning of time, no end), and the sum of new due less current due (n/a
 *  as 0.00). A claim bound by a statement or settled keeps its figure. Nothing is saved. */
export function ratePreview(
  people: { grades: Grades; claims: Claim[]; late?: Late }[],
  rates: Rate[] | undefined,
  grade: string,
  pct: string,
  floor: Floor,
): { count: number; diff: string } {
  const candidate: Rate[] = [...(rates ?? []).filter((r) => r.grade !== grade || (r.level ?? 0) > 0), { grade, pct, from: null, to: null }];
  const figure = (d: string) => (d === NA ? 0n : hundredths(d));
  let count = 0;
  let diff = 0n;
  for (const p of people) {
    for (const c of p.claims) {
      if (c.status !== 'OPEN' && c.status !== 'PENDING') continue;
      if (gradeOn(p.grades, c.date) !== grade) continue;
      const now = claimDue(c, rates, p.grades, floor, p.late);
      const then = claimDue(c, candidate, p.grades, floor, p.late);
      if (now === then) continue;
      count += 1;
      diff += figure(then) - figure(now);
    }
  }
  return { count, diff: format(diff) };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';
import { asNumber, asString, useSearchParam } from '../../url/useSearchParam';
import { type Hold, covers } from '../people/people';

/** PENDING: settled by a clerk above the clerk limit, awaiting a steward's approval; handled as OPEN,
 *  except that a statement does not bind it while it is PENDING. DELETED: a deleted DRAFT, which counts
 *  nowhere and can be restored to a DRAFT on the sheet's today it was deleted. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

/** Every status the summary and header count, whether or not a claim can reach it; a DELETED claim counts nowhere. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const satisfies readonly ClaimStatus[];

/** How many of these claims have the status. */
export const statusCount = (claims: Claim[] | undefined, status: ClaimStatus) =>
  (claims ?? []).filter((c) => c.status === status).length;

/** `amount` has two decimals; `date` is yyyy-MM-dd; `number` is given when the claim is opened
 *  (null for a draft or a voided claim): the sheet-wide 1, 2, ... or, numbered per period, <period>-<n> / X-<n>. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  /** The due fixed when the claim was settled; null when it has none, so its due follows the rate. */
  due: string | null;
  /** The user who opened the claim; null until it is opened. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim to its figure then. */
  stated: boolean;
  /** The figure the claim was bound to; null when not bound, or bound while it had none. */
  statedDue: string | null;
  /** Whether the statement bound the claim to n/a: the rate that would apply to it had ended (its to-date). */
  statedNa: boolean;
  /** The number of the settled claim a correction (a negative amount) corrects; null for any other claim. */
  corrects: string | null;
  /** The date (yyyy-MM-dd) its live figures round by: its own, or for a correction that of the claim it corrects. */
  roundsBy: string;
  /** The date (yyyy-MM-dd) it is due by, fixed when it was added as the terms-th business day after its date. */
  dueBy: string;
  /** Its status log, oldest first: `<STATUS> by <user> on <date> due=<due>`, one line per status it has had. */
  log: string[];
  /** Whether it is deferred on the sheet's today: OPEN and deferred until a date after it. Until then it
   *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. A VOID claim
   *  deferred until after it shows as deferred too, though it counts nowhere. */
  deferred: boolean;
  /** The date (yyyy-MM-dd) it was last deferred until; null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs it has: a claim due above the proof threshold on its date cannot be settled or approved with none. */
  proofs: number;
  /** The number of the claim it was split off; null when it was not split off another. */
  splitFrom: string | null;
  /** Whether it was added while the period its due-by falls in was soft-closed. */
  lateEntry: boolean;
  /** The date (yyyy-MM-dd) a reminder was last written for it; null when it was never reminded. */
  remindedOn: string | null;
  /** Its external reference, unique on the sheet without regard to case; null when it has none. */
  ref: string | null;
  /** Its tags, each trimmed and lower-cased, sorted; empty when it has none. */
  tags: string[];
  /** The reason it was voided with, from the sheet's list then; null when none. */
  voidReason: string | null;
  /** Its comments, oldest first: `<user> on <date>: <text>`, the date the sheet's today when it was written. */
  comments: string[];
  /** The bulk settle batch it was settled in (1, 2, ... on the sheet); null when settled one at a time, or not settled. */
  batch: number | null;
  /** Its lines, in the order added: `<label> <qty> x <unit>`; a claim with lines has their sum as its amount. */
  lines: string[];
};

/** A correction: a claim with a negative amount, which has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;

/** Whether the claim is open: OPEN, or PENDING, which is handled as open. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Only OPEN, PENDING and SETTLED claims count toward claimed and the totals; a deferred claim does not. */
export const counts = (c: Claim) => (isOpen(c) && !c.deferred) || c.status === 'SETTLED';

/** Whether the claim keeps the figure (or n/a) its person's last statement bound it to: not while PENDING. */
export const isBound = (c: Claim) => c.stated && (c.statedDue !== null || c.statedNa) && c.status !== 'PENDING';

/** These claims less the OPEN (or PENDING) claims dated within one of their person's holds, or of a
 *  person whose retirement date the sheet's today has reached, which count in no live total, unless a
 *  statement bound them. */
export const live = (claims: Claim[], people: { id: number; holds: Hold[]; retiredNow: boolean }[] | undefined) => {
  const byId = new Map((people ?? []).map((p) => [p.id, p]));
  return claims.filter((c) => {
    const p = byId.get(c.personId);
    return !(isOpen(c) && !c.stated && p !== undefined && (p.retiredNow || p.holds.some((h) => covers(h, c.date))));
  });
};

/** The date (yyyy-MM-dd) the given number of days before this one. */
const daysBefore = (date: string, days: number) => {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - days);
  return d.toISOString().slice(0, 10);
};

/** Whether a person is active on the date (yyyy-MM-dd): one of their claims (already filtered to those
 *  live) is OPEN or PENDING, counts, and is dated within the 30 days up to and including the date. */
export const isActive = (claims: Claim[], today: string | undefined) =>
  today !== undefined &&
  claims.some((c) => isOpen(c) && counts(c) && c.date > daysBefore(today, 30) && c.date <= today);

/** Whether the claim is SETTLED and dated within the 90 days up to and including the date (yyyy-MM-dd). */
export const isRecentSettled = (c: Claim, today: string | undefined) =>
  today !== undefined && c.status === 'SETTLED' && c.date > daysBefore(today, 90) && c.date <= today;

/** Under the sheet's key, so loading the sheet again re-reads its claims. */
export const claimsKey = (sheet: string) => [...sheetKey(sheet), 'claims'] as const;

/** Under the claims' key, so whatever re-reads the claims re-reads the tags too. */
export const tagsKey = (sheet: string) => [...claimsKey(sheet), 'tags'] as const;

/** Every tag ever carried by a claim on the sheet, sorted. */
export function useTags(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(tagsKey(sheet), asOf),
    queryFn: () => getJson<string[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/tags`, asOf)),
    enabled: sheet !== '',
  });
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(claimsKey(sheet), asOf),
    queryFn: () => getJson<Claim[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/claims`, asOf)),
    enabled: sheet !== '',
  });
}

/** Amounts are added in whole cents, so the sum is exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** Whether the claim corrects another: it names the number of the claim it corrects. */
export const correctsAnother = (c: Claim) => c.corrects !== null && c.corrects.trim() !== '';

/** The sum of the amounts of those of these claims that count, leaving out claims that correct another,
 *  with two decimals. */
export function claimed(claims: Claim[]): string {
  return (claims.filter((c) => counts(c) && !correctsAnother(c)).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}

/** The ids of the claims selected for a bulk action, kept in the URL (`selectedClaims`, comma separated). */
export function useSelectedClaims(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selectedClaims', asString);
  const ids = raw.split(',').filter((s) => s !== '').map(Number).filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.join(','))];
}

/** The id of the claim whose editor is open, and locked by this user, kept in the URL (`editClaim`). */
export const useEditingClaim = () => useSearchParam('editClaim', asNumber);

import { type ChangeEvent, useEffect, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, peopleKey, usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { claimDue, useRates } from '../rates/rates';
import { floorOf, useSettings } from '../settings/settings';
import { periodOf, usePeriods } from '../periods/periods';
import { useSheetToday } from '../sheet/sheet';
import { dueBy, lateOf, overdue } from '../overdue/overdue';
import { useVoidReasons } from '../voidreasons/voidreasons';
import { useTemplates } from '../templates/templates';
import { type Claim, type ClaimStatus, claimsKey, useClaims, useEditingClaim, useSelectedClaims } from './claims';

type Fields = { amount: string; date: string; note: string; corrects: string; ref: string; tags: string };
/** `review` for a steward approving (SETTLED) or rejecting (OPEN, with a reason) a PENDING claim. */
type StatusChange = { id: number; status: ClaimStatus; review?: boolean; reason?: string };
/** A steward moving a claim to another person (`to`, their id). */
type Reassign = { id: number; to: string };
const EMPTY: Fields = { amount: '', date: '', note: '', corrects: '', ref: '', tags: '' };

function ClaimsHead() {
  return <th>Claims</th>;
}

// A person's claims, newest first, each with its status and the buttons that move it on, and the
// form that adds one or edits the one whose editor is open.
function PersonClaims({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const settings = useSettings(sheet).data;
  const floor = floorOf(settings);
  const today = useSheetToday(sheet);
  const periods = usePeriods(sheet);
  const [fields, setFields] = useState<Fields>(EMPTY);
  // The claim whose editor is open (and locked by this user), kept in the URL so it outlives a re-load
  // of the sheet; this person's form edits it when it is one of theirs.
  const [editingId, setEditing] = useEditingClaim();
  const editingClaim = (claims.data ?? []).find((c) => c.id === editingId && c.personId === person.id);
  const editing = editingClaim?.id;
  const [reasons, setReasons] = useState<Record<number, string>>({});
  // The void reason chosen per claim, from the sheet's list; a void needs one while the list is not empty.
  const voidReasons = useVoidReasons(sheet).data ?? [];
  const [voidChoices, setVoidChoices] = useState<Record<number, string>>({});
  const [targets, setTargets] = useState<Record<number, string>>({});
  const [deferDates, setDeferDates] = useState<Record<number, string>>({});
  const [redates, setRedates] = useState<Record<number, string>>({});
  const [splitAmounts, setSplitAmounts] = useState<Record<number, string>>({});
  const [inlineAmounts, setInlineAmounts] = useState<Record<number, string>>({});
  const [commentTexts, setCommentTexts] = useState<Record<number, string>>({});
  const [lineFields, setLineFields] = useState<Record<number, { label: string; qty: string; unit: string }>>({});
  const people = usePeople(sheet);
  const [selected, setSelected] = useSelectedClaims();
  const queryClient = useQueryClient();
  const base = `/api/sheets/${encodeURIComponent(sheet)}`;

  const save = useMutation({
    mutationFn: (f: Fields) =>
      editing !== undefined
        ? putJson<Claim>(`${base}/claims/${editing}`, { ...f, user })
        : postJson<Claim>(`${base}/people/${person.id}/claims`, { ...f, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      setFields(EMPTY);
      setEditing(undefined);
    },
  });

  const submit = useSubmitOnce(save);

  // A DRAFT claim made from a template: the server takes the template's amount and note as they are
  // now and dates it as the form dates a blank date; a refusal shows as the form's error.
  const templates = useTemplates(sheet).data ?? [];
  const [template, setTemplate] = useState('');
  const fromTemplate = useMutation({
    mutationFn: (name: string) => postJson<Claim>(`${base}/people/${person.id}/template-claims`, { template: name, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });
  const submitTemplate = useSubmitOnce(fromTemplate);

  // Opening a claim's editor locks it for every other user; the server refuses a claim that cannot be
  // edited or that another user has locked, and the error shows on that claim.
  const lock = useMutation({
    mutationFn: (c: Claim) => postJson<Claim>(`${base}/claims/${c.id}/lock`, { user }),
    onSuccess: (_, c) => {
      if (editingId !== undefined && editingId !== c.id) release(editingId);
      setEditing(c.id);
      setFields({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '', ref: c.ref ?? '', tags: c.tags.join(', ') });
    },
  });
  // Cancelling an editor releases its lock.
  const release = (id: number) => {
    void postJson<Claim>(`${base}/claims/${id}/unlock`, { user }).catch(() => undefined);
  };

  // The server refuses a change the claim's status does not allow; the error shows on that claim.
  const move = useMutation({
    mutationFn: (m: StatusChange) =>
      postJson<Claim>(`${base}/claims/${m.id}/status`, { status: m.status, user, review: m.review ?? false, reason: m.reason ?? '' }),
    onSuccess: async (_, m) => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      if (m.review) setReasons((r) => ({ ...r, [m.id]: '' }));
    },
  });
  const moveTo = (id: number, status: ClaimStatus, review?: { reason: string }, voidReason?: string) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    move.mutate({ id, status, review: review !== undefined, reason: review?.reason ?? voidReason });
  };

  // Moving a claim re-reads the people too: both people's figures follow it.
  const reassign = useMutation({
    mutationFn: (r: Reassign) => postJson<Claim>(`${base}/claims/${r.id}/reassign`, { to: r.to, user }),
    onSuccess: async (_, r) => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
      setTargets((t) => ({ ...t, [r.id]: '' }));
    },
  });
  const reassignTo = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    reassign.mutate({ id, to: targets[id] ?? '' });
  };
  // A steward re-settling a SETTLED claim freezes it again at today's figure.
  const resettle = useMutation({
    mutationFn: (id: number) => postJson<Claim>(`${base}/claims/${id}/resettle`, { user }),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
  });
  const resettleClaim = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    resettle.mutate(id);
  };
  // Deferring an OPEN claim until a date after today takes it out of every figure until then.
  const defer = useMutation({
    mutationFn: (d: { id: number; until: string }) =>
      postJson<Claim>(`${base}/claims/${d.id}/defer`, { until: d.until, user }),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
  });
  const deferClaim = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    defer.mutate({ id, until: (deferDates[id] ?? '').trim() });
  };
  // Reminding an OPEN or PENDING claim marks it reminded on the sheet's today; once per day.
  const remind = useMutation({
    mutationFn: (id: number) => postJson<Claim>(`${base}/claims/${id}/remind`, { user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });
  const remindClaim = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    remind.mutate(id);
  };
  // A comment is kept on the claim, in any status, with its writer and the sheet's today; not an empty one.
  const comment = useMutation({
    mutationFn: (d: { id: number; text: string }) =>
      postJson<Claim>(`${base}/claims/${d.id}/comment`, { text: d.text, user }),
    onSuccess: async (_, d) => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      setCommentTexts((t) => ({ ...t, [d.id]: '' }));
    },
  });
  const addComment = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    comment.mutate({ id, text: commentTexts[id] ?? '' });
  };
  // A line on a DRAFT claim makes its amount the sum of its lines; an edit of the claim, refused like one.
  const line = useMutation({
    mutationFn: (d: { id: number; label: string; qty: string; unit: string }) =>
      postJson<Claim>(`${base}/claims/${d.id}/line`, { label: d.label, qty: d.qty, unit: d.unit, user }),
    onSuccess: async (_, d) => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
      setLineFields((l) => ({ ...l, [d.id]: { label: '', qty: '', unit: '' } }));
    },
  });
  const addLine = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    const f = lineFields[id] ?? { label: '', qty: '', unit: '' };
    line.mutate({ id, label: f.label.trim(), qty: f.qty.trim(), unit: f.unit.trim() });
  };
  const setLine = (id: number, key: 'label' | 'qty' | 'unit') => (e: ChangeEvent<HTMLInputElement>) => {
    setLineFields({ ...lineFields, [id]: { ...(lineFields[id] ?? { label: '', qty: '', unit: '' }), [key]: e.target.value } });
    if (line.variables?.id === id) line.reset();
  };
  // A proof raises the claim's proofs count by one; not on a SETTLED or VOID claim.
  const proof = useMutation({
    mutationFn: (id: number) => postJson<Claim>(`${base}/claims/${id}/proof`, { user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });
  const addProof = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    proof.mutate(id);
  };
  // Splitting an amount off an OPEN claim lists a new OPEN claim with it; both people's figures follow.
  const split = useMutation({
    mutationFn: (d: { id: number; amount: string }) =>
      postJson<Claim>(`${base}/claims/${d.id}/split`, { amount: d.amount, user }),
    onSuccess: async (_, d) => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
      setSplitAmounts((a) => ({ ...a, [d.id]: '' }));
    },
  });
  const splitClaim = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    split.mutate({ id, amount: (splitAmounts[id] ?? '').trim() });
  };
  // A steward re-dates an OPEN or PENDING claim; its due-by, and so its period (and per-period number), stay as they are.
  const redate = useMutation({
    mutationFn: (d: { id: number; date: string }) =>
      postJson<Claim>(`${base}/claims/${d.id}/redate`, { date: d.date, user }),
    onSuccess: async (_, d) => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
      setRedates((a) => ({ ...a, [d.id]: '' }));
    },
  });
  const redateClaim = (id: number) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.mutate({ id, date: (redates[id] ?? '').trim() });
  };
  // A draft's amount changed in its row: an edit as the claim form makes it, keeping the claim's date, note,
  // the claim it corrects, its reference and its tags, so the server applies the form's rules and records CLAIM_EDITED.
  const inline = useMutation({
    mutationFn: (d: { claim: Claim; amount: string }) =>
      putJson<Claim>(`${base}/claims/${d.claim.id}`, {
        amount: d.amount,
        date: d.claim.date,
        note: d.claim.note,
        corrects: d.claim.corrects ?? '',
        ref: d.claim.ref ?? '',
        tags: d.claim.tags.join(','),
        user,
      }),
    onSuccess: async (_, d) => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
      setInlineAmounts((a) => ({ ...a, [d.claim.id]: '' }));
    },
  });
  const saveInline = (c: Claim) => {
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    inline.mutate({ claim: c, amount: (inlineAmounts[c.id] ?? '').trim() });
  };
  // The refusal of the last status change, move, re-settle, deferral, reminder, comment, proof, split or re-dating of the claim, as the server gave it; null when none.
  const refusal = (id: number) => {
    const error =
      move.isError && move.variables?.id === id
        ? move.error
        : reassign.isError && reassign.variables?.id === id
          ? reassign.error
          : resettle.isError && resettle.variables === id
            ? resettle.error
            : defer.isError && defer.variables?.id === id
              ? defer.error
              : remind.isError && remind.variables === id
                ? remind.error
                : comment.isError && comment.variables?.id === id
                  ? comment.error
                : line.isError && line.variables?.id === id
                  ? line.error
                : proof.isError && proof.variables === id
                  ? proof.error
                  : split.isError && split.variables?.id === id
                    ? split.error
                    : redate.isError && redate.variables?.id === id
                      ? redate.error
                      : inline.isError && inline.variables?.claim.id === id
                        ? inline.error
                        : lock.isError && lock.variables?.id === id
                          ? lock.error
                          : null;
    if (error === null) return null;
    return error instanceof HttpError && error.reason ? `${error.reason}.` : 'The change was refused.';
  };

  const set = (key: keyof Fields) => (e: ChangeEvent<HTMLInputElement>) => {
    setFields({ ...fields, [key]: e.target.value });
    save.reset();
    fromTemplate.reset();
  };
  const open = (c: Claim) => {
    save.reset();
    fromTemplate.reset();
    move.reset();
    lock.reset();
    reassign.reset();
    resettle.reset();
    defer.reset();
    remind.reset();
    comment.reset();
    line.reset();
    proof.reset();
    split.reset();
    redate.reset();
    inline.reset();
    lock.mutate(c);
  };
  const cancel = () => {
    save.reset();
    fromTemplate.reset();
    lock.reset();
    if (editing !== undefined) release(editing);
    setEditing(undefined);
    setFields(EMPTY);
  };

  // An editor still open when the sheet is shown again fills the form with its claim.
  useEffect(() => {
    if (editingClaim) {
      setFields({
        amount: editingClaim.amount,
        date: editingClaim.date,
        note: editingClaim.note,
        corrects: editingClaim.corrects ?? '',
        ref: editingClaim.ref ?? '',
        tags: editingClaim.tags.join(', '),
      });
    }
  }, [editing]);

  return (
    <td>
      <ul>
        {(claims.data ?? [])
          .filter((c) => c.personId === person.id)
          .map((c) => (
            <li key={c.id} data-testid={`claim-row-${c.id}`}>
              <input
                type="checkbox"
                data-testid="claim-select"
                aria-label="Select claim"
                checked={selected.includes(c.id)}
                onChange={(e) => setSelected(e.target.checked ? [...selected, c.id] : selected.filter((id) => id !== c.id))}
              />{' '}
              <span data-testid="claim-number">{c.number ?? ''}</span>{' '}
              <span data-testid="claim-amount">{c.amount}</span>{' '}
              <span data-testid="claim-date">{c.date}</span>{' '}
              <span data-testid="claim-note">{c.note}</span>{' '}
              <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
              <span data-testid="claim-ref">{c.ref ?? ''}</span>{' '}
              <span data-testid="claim-tags">{c.tags.join(', ')}</span>{' '}
              <span data-testid="claim-period">{periodOf(periods.data, c.dueBy)?.name ?? ''}</span>{' '}
              <span data-testid="claim-due">{claimDue(c, rates.data, person.grades, floor, lateOf(settings, today, [person]))}</span>{' '}
              <span data-testid="claim-due-by">{dueBy(c)}</span>{' '}
              <span data-testid="claim-overdue">{overdue(c, today, lateOf(settings, today, [person])) ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-status">{c.status}</span>{' '}
              <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
              <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-deferred">{c.deferred ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-deferred-until">{c.deferredUntil ?? ''}</span>{' '}
              <span data-testid="claim-reminded">{c.remindedOn ?? ''}</span>{' '}
              <span data-testid="claim-split-from">{c.splitFrom ?? ''}</span>{' '}
              <span data-testid="claim-batch">{c.batch ?? ''}</span>{' '}
              <span data-testid="claim-late-entry">{c.lateEntry ? 'yes' : 'no'}</span>{' '}
              <button type="button" data-testid="claim-open" disabled={move.isPending} onClick={() => moveTo(c.id, 'OPEN')}>
                Open
              </button>{' '}
              <button type="button" data-testid="claim-settle" disabled={move.isPending} onClick={() => moveTo(c.id, 'SETTLED')}>
                Settle
              </button>{' '}
              {voidReasons.length > 0 && (
                <select
                  data-testid="claim-void-reason"
                  aria-label="Void reason"
                  value={voidChoices[c.id] ?? ''}
                  onChange={(e) => {
                    setVoidChoices({ ...voidChoices, [c.id]: e.target.value });
                    if (move.variables?.id === c.id) move.reset();
                  }}
                >
                  <option value="">(void reason)</option>
                  {voidReasons.map((r) => (
                    <option key={r.reason} value={r.reason}>
                      {r.reason}
                    </option>
                  ))}
                </select>
              )}{' '}
              <button
                type="button"
                data-testid="claim-void"
                disabled={move.isPending}
                onClick={() => moveTo(c.id, 'VOID', undefined, voidChoices[c.id] ?? '')}
              >
                Void
              </button>{' '}
              <button type="button" data-testid="claim-delete" disabled={move.isPending} onClick={() => moveTo(c.id, 'DELETED')}>
                Delete
              </button>{' '}
              <button type="button" data-testid="claim-restore" disabled={move.isPending} onClick={() => moveTo(c.id, 'DRAFT')}>
                Restore
              </button>{' '}
              <button
                type="button"
                data-testid="claim-resettle"
                disabled={resettle.isPending}
                onClick={() => resettleClaim(c.id)}
              >
                Re-settle
              </button>{' '}
              <button
                type="button"
                data-testid="claim-approve"
                disabled={move.isPending}
                onClick={() => moveTo(c.id, 'SETTLED', { reason: '' })}
              >
                Approve
              </button>{' '}
              <input
                data-testid="claim-reject-reason"
                placeholder="Reason"
                aria-label="Reject reason"
                value={reasons[c.id] ?? ''}
                onChange={(e) => {
                  setReasons({ ...reasons, [c.id]: e.target.value });
                  if (move.variables?.id === c.id) move.reset();
                }}
              />{' '}
              <button
                type="button"
                data-testid="claim-reject"
                disabled={move.isPending}
                onClick={() => moveTo(c.id, 'OPEN', { reason: reasons[c.id] ?? '' })}
              >
                Reject
              </button>{' '}
              <select
                data-testid="claim-reassign-to"
                aria-label="Move to"
                value={targets[c.id] ?? ''}
                onChange={(e) => {
                  setTargets({ ...targets, [c.id]: e.target.value });
                  if (reassign.variables?.id === c.id) reassign.reset();
                }}
              >
                <option value="">Move to…</option>
                {(people.data ?? [])
                  .filter((p) => p.id !== person.id)
                  .map((p) => (
                    <option key={p.id} value={String(p.id)}>
                      {p.name}
                    </option>
                  ))}
              </select>{' '}
              <button
                type="button"
                data-testid="claim-reassign"
                disabled={reassign.isPending}
                onClick={() => reassignTo(c.id)}
              >
                Move
              </button>{' '}
              <input
                data-testid="claim-defer-date"
                type="date"
                aria-label="Defer until"
                value={deferDates[c.id] ?? ''}
                onChange={(e) => {
                  setDeferDates({ ...deferDates, [c.id]: e.target.value });
                  if (defer.variables?.id === c.id) defer.reset();
                }}
              />{' '}
              <button type="button" data-testid="claim-defer" disabled={defer.isPending} onClick={() => deferClaim(c.id)}>
                Defer
              </button>{' '}
              <button type="button" data-testid="claim-remind" disabled={remind.isPending} onClick={() => remindClaim(c.id)}>
                Remind
              </button>{' '}
              <input
                data-testid="claim-date-new"
                type="date"
                aria-label="New date"
                value={redates[c.id] ?? ''}
                onChange={(e) => {
                  setRedates({ ...redates, [c.id]: e.target.value });
                  if (redate.variables?.id === c.id) redate.reset();
                }}
              />{' '}
              <button type="button" data-testid="claim-redate" disabled={redate.isPending} onClick={() => redateClaim(c.id)}>
                Re-date
              </button>{' '}
              <span data-testid="claim-proofs">{c.proofs ?? 0}</span>{' '}
              <button type="button" data-testid="claim-proof" disabled={proof.isPending} onClick={() => addProof(c.id)}>
                Add proof
              </button>{' '}
              <input
                data-testid="claim-split-amount"
                placeholder="Split off"
                aria-label="Amount to split off"
                inputMode="decimal"
                value={splitAmounts[c.id] ?? ''}
                onChange={(e) => {
                  setSplitAmounts({ ...splitAmounts, [c.id]: e.target.value });
                  if (split.variables?.id === c.id) split.reset();
                }}
              />{' '}
              <button type="button" data-testid="claim-split" disabled={split.isPending} onClick={() => splitClaim(c.id)}>
                Split
              </button>{' '}
              <input
                data-testid="claim-inline-amount"
                placeholder="Amount"
                aria-label="New amount"
                inputMode="decimal"
                value={inlineAmounts[c.id] ?? ''}
                onChange={(e) => {
                  setInlineAmounts({ ...inlineAmounts, [c.id]: e.target.value });
                  if (inline.variables?.claim.id === c.id) inline.reset();
                }}
              />{' '}
              <button type="button" data-testid="claim-inline-save" disabled={inline.isPending} onClick={() => saveInline(c)}>
                Save amount
              </button>{' '}
              <button type="button" data-testid="claim-edit" disabled={lock.isPending} onClick={() => open(c)}>
                Edit
              </button>
              {editing === c.id && (
                <button type="button" data-testid="claim-cancel" onClick={cancel}>
                  Cancel
                </button>
              )}
              {refusal(c.id) !== null && (
                <span data-testid="claim-error" role="alert">
                  {' '}
                  {refusal(c.id)}
                </span>
              )}
              <input
                data-testid="claim-comment-text"
                placeholder="Comment"
                aria-label="Comment"
                value={commentTexts[c.id] ?? ''}
                onChange={(e) => {
                  setCommentTexts({ ...commentTexts, [c.id]: e.target.value });
                  if (comment.variables?.id === c.id) comment.reset();
                }}
              />{' '}
              <button type="button" data-testid="claim-comment-add" disabled={comment.isPending} onClick={() => addComment(c.id)}>
                Comment
              </button>
              <input
                data-testid="claim-line-label"
                placeholder="Line"
                aria-label="Line label"
                value={lineFields[c.id]?.label ?? ''}
                onChange={setLine(c.id, 'label')}
              />{' '}
              <input
                data-testid="claim-line-qty"
                placeholder="Qty"
                aria-label="Line quantity"
                inputMode="numeric"
                value={lineFields[c.id]?.qty ?? ''}
                onChange={setLine(c.id, 'qty')}
              />{' '}
              <input
                data-testid="claim-line-unit"
                placeholder="Unit"
                aria-label="Line unit amount"
                inputMode="decimal"
                value={lineFields[c.id]?.unit ?? ''}
                onChange={setLine(c.id, 'unit')}
              />{' '}
              <button type="button" data-testid="claim-line-add" disabled={line.isPending} onClick={() => addLine(c.id)}>
                Add line
              </button>
              <ol data-testid="claim-lines">
                {(c.lines ?? []).map((l, i) => (
                  <li key={i} data-testid="claim-lines-line">
                    {l}
                  </li>
                ))}
              </ol>
              <ol data-testid="claim-comments">
                {(c.comments ?? []).map((line, i) => (
                  <li key={i} data-testid="claim-comments-line">
                    {line}
                  </li>
                ))}
              </ol>
              <ol data-testid="claim-log">
                {(c.log ?? []).map((line, i) => (
                  <li key={i} data-testid="claim-log-line">
                    {line}
                  </li>
                ))}
              </ol>
            </li>
          ))}
      </ul>
      <form
        data-testid="claim-form"
