import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, usePeople } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { counts, live, useClaims } from '../claims/claims';
import { floorOf, useSettings } from '../settings/settings';
import { trimmedTotal, useRates } from '../rates/rates';
import { lateOf, overdueFigures } from './overdue';

// A person's overdue count and overdue-total (the due of their overdue claims that count), and the sheet's.
function OverdueHead() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

/** A person's overdue figures on the sheet (the current sheet's unless another is named). */
export function useOverdue(of?: string) {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  return (person: Person) =>
    overdueFigures(
      live((claims.data ?? []).filter((c) => c.personId === person.id), [person]).filter(counts),
      rates.data,
      person.grades,
      floorOf(settings),
      today,
      lateOf(settings, today, [person]),
    );
}

function PersonOverdue({ person }: { person: Person }) {
  const { count, total } = useOverdue()(person);
  return (
    <>
      <td data-testid="person-overdue-count">{count}</td>
      <td data-testid="person-overdue-total">{total}</td>
    </>
  );
}

/** The sheet's overdue figures (the current sheet's unless another is named): everyone's overdue counts
 *  added up, and their overdue-totals added up trimmed of the single highest and lowest when three or more
 *  people have one. */
export function useSheetOverdue(of?: string): { count: number; total: string } {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const people = usePeople(sheet);
  const figures = (people.data ?? []).map(useOverdue(sheet));
  return { count: figures.reduce((n, f) => n + f.count, 0), total: trimmedTotal(figures.map((f) => f.total)) };
}

function OverdueTotal() {
  const { count, total } = useSheetOverdue();
  return (
    <p>
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong>{' '}
      Overdue total <strong data-testid="rollup-overdue-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 17, Component: OverdueHead }),
  PersonColumns.fill({ order: 17, Component: PersonOverdue }),
  HomeMain.fill({ order: 36, Component: OverdueTotal }),
];
import { type Claim, isOpen } from '../claims/claims';
import { type Floor, type Late, type Rate, claimDue, dueTotal } from '../rates/rates';
import { type Settings, graceOf, latePctOf } from '../settings/settings';
import { type Grades, type Person, gradeOn } from '../people/people';

const DAY = 24 * 60 * 60 * 1000;

/** The claim's due-by (yyyy-MM-dd): fixed when it was added, from the terms of its person's grade then. */
export const dueBy = (claim: Claim): string => claim.dueBy;

/** The date (yyyy-MM-dd) the claim's overdue counts from: its due-by plus the grace days in force on its date for
 *  its person's grade then (its due-by when none, or when the late charge is not known). */
export const graceBy = (claim: Claim, late?: Late): string => late?.graceBy?.(claim) ?? dueBy(claim);

/** Whether the claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by plus any grace is before the sheet's today. */
export function overdue(claim: Claim, today: string | undefined, late?: Late): boolean {
  return isOpen(claim) && !claim.deferred && today !== undefined && graceBy(claim, late) < today;
}

/** The date `days` after the date (yyyy-MM-dd). */
const plusDays = (date: string, days: number): string =>
  new Date(Date.parse(`${date}T00:00:00Z`) + days * DAY).toISOString().slice(0, 10);

/** How many full 30 days the claim is overdue on the sheet's today, counted from its due-by plus any grace (0 when it is not overdue). */
export function latePeriods(claim: Claim, today: string | undefined, late?: Late): number {
  if (today === undefined || !overdue(claim, today, late)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${graceBy(claim, late)}T00:00:00Z`)) / DAY;
  return Math.floor(days / 30);
}

/** The 30-day boundaries (yyyy-MM-dd) the claim is overdue past on the sheet's today: its due-by plus any grace, plus 30, 60, 90 ... days. */
export function lateBoundaries(claim: Claim, today: string | undefined, late?: Late): string[] {
  const start = Date.parse(`${graceBy(claim, late)}T00:00:00Z`);
  return Array.from({ length: latePeriods(claim, today, late) }, (_, i) =>
    new Date(start + (i + 1) * 30 * DAY).toISOString().slice(0, 10));
}

/** What the sheet's late charge follows: its late percent in force on each boundary date, each claim's due-by plus
 *  the grace days in force on its date for its person's grade then (of these people), and its today; and how it rounds:
 *  a claim rounding by a date before the policy date (else the sheet's today) rounds half up. */
export function lateOf(settings: Settings | undefined, today: string | undefined, people: Person[] | undefined): Late {
  const policy = settings?.policyDate ?? today;
  const pcts = latePctOf(settings);
  const graces = graceOf(settings);
  const late: Late = {
    pct: pcts,
    boundaries: (c) => lateBoundaries(c, today, late),
    halfUp: (c) => policy !== undefined && (c.roundsBy ?? c.date) < policy,
    graceBy: (c) => {
      const person = people?.find((p) => p.id === c.personId);
      const grace = person && graces?.(gradeOn(person.grades, c.date), c.date);
      return grace == null ? dueBy(c) : plusDays(dueBy(c), grace);
    },
  };
  return late;
}

/** A person's overdue claims among these (their claims that count): how many, and the sum of their
 *  dues (late charge included) at the person's grade in force on each claim's date, skipping n/a. */
export function overdueFigures(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  floor: Floor,
  today: string | undefined,
  lateCharge?: Late,
): { count: number; total: string } {
  const late = claims.filter((c) => overdue(c, today, lateCharge));
  return { count: late.length, total: dueTotal(late.map((c) => claimDue(c, rates, grades, floor, lateCharge))) };
}
import { useMutationState, useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** `version` moves on with each stored edit; an edit is saved only over the version its editor loaded.
 *  `statementCount` is how many statements were taken of them; `statedTotal` (two decimals, or n/a)
 *  and `statementDate` (yyyy-MM-dd) are the last one's, null when none was taken. `retired` is set
 *  as soon as a `retiredFrom` date (yyyy-MM-dd, null when not retired) is, whatever the date;
 *  `retiredNow` once the sheet's today reaches it: from then their OPEN claims count in no live total
 *  unless a statement bound them, as a hold's would.
 *  `holds` are their holds, oldest first; `held` whether they have any. Their OPEN claims dated within
 *  a hold count in no live total unless a statement bound them; their SETTLED ones still do.
 *  `patronIds` are the ids of the other people on the sheet they named as their patrons, in the order they named them.
 *  `grade` is the grade in force on the sheet's today; `grades` every grade with the date it applies from.
 *  `terms` are their own terms in whole days (null when none), ahead of their grade's and the sheet's.
 *  `contact` is their contact (trimmed, lower-cased; null when none), no other person's on the sheet.
 *  `aliases` are other names they are found by (no name or other alias on the sheet), sorted as names are compared.
 *  `clashing` whether their name or an alias is used as a name or alias on another sheet of the sheet's tree (its
 *  ancestors and descendants); every edit of them is refused until it renames them to a name that does not clash.
 *  `origin` is the id of the sheet they were transferred from (null when they were not).
 *  `pastRetirements` are the retirements they were unretired from, oldest first.
 *  `tags` are their tags (trimmed, lower-cased, no repeats), sorted; a claim counts for a tag when it or its
 *  person carries it.
 *  `snapshots` are their snapshots, one per SNAPSHOT written for them as the sheet's today moved on, oldest first. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: Grades;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  retiredNow: boolean;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  pastRetirements: PastRetirement[];
  tags: string[];
  snapshots: Snapshot[];
};

/** A snapshot: the day being left (yyyy-MM-dd) and the person's due-total as it stood then (two decimals, or n/a). */
export type Snapshot = { day: string; dueTotal: string };

/** A past retirement: from the date retired from to the day unretired (yyyy-MM-dd). No claim dated
 *  after its from-date and before its to-date may be added. */
export type PastRetirement = { from: string; to: string };

/** A hold from its from-date to its to-date (yyyy-MM-dd, both inclusive; null for no end). */
export type Hold = { from: string; to: string | null };

/** Whether the hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => h.from <= date && (h.to === null || date <= h.to);

export const GRADES = ['A', 'B', 'C'] as const;

/** A person's grades, each with the date (yyyy-MM-dd) it applies from; the first has none (null),
 *  applying from the beginning of time. */
export type Grades = { grade: string; from: string | null }[];

/** The grade in force on the date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(grades: Grades, on: string | undefined): string {
  let best = grades[0];
  for (const g of grades) {
    if (g.from === null || (on !== undefined && g.from <= on)) {
      if ((best.from ?? '') <= (g.from ?? '')) best = g;
    }
  }
  return best?.grade ?? 'A';
}

/** Under the sheet's key, so loading the sheet again re-reads its people. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

export function usePeople(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(peopleKey(sheet), asOf),
    queryFn: () => getJson<Person[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/people`, asOf)),
    enabled: sheet !== '',
  });
}

/** The id of the person whose editor is open in the person form ('' when it adds). */
export const useEditingPerson = () => useSearchParam('editPerson', asString);

/** Whether the people list shows retired people too; off when the screen is first opened. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);

/** The mutation key of an action on a person's row (a statement, a hold, a retirement): the row
 *  shows only the error of the latest one taken, so taking the next action clears an earlier one's. */
export const personActionKey = (sheet: string, personId: number) => [...peopleKey(sheet), personId, 'action'] as const;

/** When the latest action on the person's row was taken (0 when none was). */
export function useLatestPersonAction(sheet: string, personId: number): number {
  const taken = useMutationState({
    filters: { mutationKey: personActionKey(sheet, personId) },
    select: (m) => m.state.submittedAt,
  });
  return Math.max(0, ...taken);
}

/** The ids of the people selected for a bulk grade, kept in the URL (`selectedPeople`, comma separated). */
export function useSelectedPeople(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selectedPeople', asString);
  const ids = raw.split(',').filter((s) => s !== '').map(Number).filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.join(','))];
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** The sheet's settings: `clerkLimit` (two decimals) is the most due a clerk may settle a claim at,
 *  null for no limit; `floor` (two decimals) is the least a claim's live due may be; `terms` is the
 *  business days after its date a claim is due by; `latePct` (two decimals) is the percent of an overdue
 *  claim's figure plus its earlier charges (compounding) charged at each full 30 days it is overdue (the one in force on that boundary); `policyDate` (yyyy-MM-dd) is the date
 *  rounding turns on, null when blank (then the sheet's today); `periodNumberingFrom` (yyyy-MM-dd) is the
 *  date from which claims opened are numbered per period, null when blank (off); `gradeTerms` is the terms
 *  in force for each grade (its own, else the sheet's), by grade; `cap` (two decimals) is the most a person's
 *  due-total may be, null for no cap; `proofThreshold` (two decimals) is the due above which a claim needs a proof
 *  before it is settled or approved, null for none; `noteThreshold` (two decimals) is the due above which a
 *  claim needs a note before it is opened, null for none. Each of these that carries a figure is the one in force on the sheet's today.
 *  `floorFrom` and `latePctFrom` are the floor and late percent recorded, oldest from-date (yyyy-MM-dd) first:
 *  a claim's floor and late percent are those in force on its date. `perms` is the permission matrix: the roles
 *  that may take each action (open, settle, void, reassign, close, reopen), comma separated, by action; null when
 *  blank (the standing rule). `graceDays` is the whole days after its to-date an open period is closed when the
 *  sheet's today moves, null when blank (off). `entryDate` (yyyy-MM-dd) is the default date of a new claim
 *  in place of the sheet's today, null when blank (off). `gradeGrace` is each grade's grace days in force on the sheet's
 *  today, by grade, null when it has none; `gradeGraceFrom` is each grade's grace days recorded, by grade, oldest
 *  from-date first: a claim's grace is the one in force on its date for its person's grade then. `gradeProofThreshold`
 *  is each grade's proof threshold in force on the sheet's today, by grade, null when it has none (then the sheet's).
 *  `pot` (two decimals) is the sum a balanced pool shares out among its members, null for none; it is not dated.
 *  `parent` is the id of the sheet whose rates a grade with no rate in force on a date takes (then its parent's, up
 *  to three levels up), null for none; it is not dated. `fiscalStartMonth` is the month (1 to 12) a fiscal year starts in,
 *  1 unless set; it is not dated. `alertThreshold` (two decimals) is the due-total above which a person
 *  crossing it raises an ALERT, null for off; it is not dated. */
export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null;
  periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; proofThreshold: string | null;
  floorFrom: Dated[]; latePctFrom: Dated[]; perms: Record<string, string | null>;
  graceDays: string | null; noteThreshold: string | null; entryDate: string | null;
  gradeGrace: Record<string, string | null>; gradeGraceFrom: Record<string, Dated[]>;
  gradeProofThreshold: Record<string, string | null>; pot: string | null; parent: string | null; fiscalStartMonth: string;
  alertThreshold: string | null };

/** A setting's value recorded from a date (yyyy-MM-dd); a null value is blank. */
export type Dated = { from: string; value: string | null };

/** The floor a sheet has before any is recorded. */
const STARTING_FLOOR = '1.00';

/** The late percent a sheet has before any is recorded. */
const STARTING_LATE_PCT = '0.00';

/** The value in force on the date: the one with the latest from-date on or before it, else `starting`. */
export function valueOn(history: Dated[], date: string, starting: string): string {
  let found: string | null = null;
  for (const d of history) if (d.from <= date) found = d.value;
  return found ?? starting;
}

/** The floor in force on each date; undefined until the settings are read. */
export function floorOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.floorFrom, date, STARTING_FLOOR));
}

/** The late percent in force on each date; undefined until the settings are read. */
export function latePctOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.latePctFrom, date, STARTING_LATE_PCT));
}

/** The grace days of a grade in force on each date (null for none); undefined until the settings are read. */
export function graceOf(settings: Settings | undefined): ((grade: string, date: string) => number | null) | undefined {
  return settings && ((grade, date) => {
    const value = valueOn(settings.gradeGraceFrom?.[grade] ?? [], date, '');
    return value === '' ? null : Number(value);
  });
}

/** The fiscal year (FY<yyyy>, by the calendar year its first day falls in) the date (yyyy-MM-dd) falls in,
 *  for a fiscal year starting on the first of the start month (1 to 12). */
export function fiscalYearOf(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
