33	    /** The sheet's figures as the store holds them now. */
34	    public Rollup snapshot(String sheetId) {
35	        LocalDate today = sheets.today(sheetId);
36	        List<Claim> all = claims.list(sheetId);
37	        BigDecimal cap = settings.cap(sheetId);
38	        Lateness lateness = lateness(sheetId, today, all);
39	        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
40	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
41	        List<BigDecimal> dues = new ArrayList<>();
42	        List<BigDecimal> overdues = new ArrayList<>();
43	        for (Person person : people.list(sheetId)) {
44	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
45	            BigDecimal due = BigDecimal.ZERO.setScale(2);
46	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
47	            boolean fixed = false;
48	            for (Claim claim : all) {
49	                if (claim.getPersonId() != person.getId()
50	                        || !counts(claim, person, today)) {
51	                    continue;
52	                }
53	                // A claim that corrects another counts toward due but not toward claimed.
54	                if (claim.getCorrects() == null || claim.getCorrects().isBlank()) {
55	                    claimed = claimed.add(claim.getAmount());
56	                }
57	                BigDecimal figure = lateness.due(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
58	                if (figure != null) {
59	                    due = due.add(figure);
60	                    if (lateness.overdue(claim)) {
61	                        overdue = overdue.add(figure);
62	                    }
63	                }
64	                // A figure at a grade other than the one in force today, or at a rate that ended before
65	                // today, does not hang on today's grade's rate.
66	                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
67	                        || (figure != null && (!person.gradeOn(claim.getDate()).equals(person.gradeOn(today))
68	                                || rates.endsBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), today)));
69	            }
70	            boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
71	            claimedTotal = claimedTotal.add(claimed);
72	            overdues.add(overdue);
73	            due = SettingStore.capped(due, cap);
74	            if (!na) {
75	                dues.add(due);
76	            }
77	            figures.put(person.getId(), new Rollup.Figures(person.getName(), shown(claimed), na ? NA : shown(due),
78	                    shown(overdue)));
79	        }
80	        return new Rollup(figures, shown(claimedTotal), shown(trimmed(dues)), shown(trimmed(overdues)));
81	    }
