235	        List<Claim> bound = claims.listForUpdate(sheetId, person.getId());
236	        // What the figures follow: the store as it is now, or as it stood at the end of the date.
237	        LocalDate on = today;
238	        Person then = person;
239	        List<Claim> all;
240	        Map<Long, Claim> was = new HashMap<>();
241	        if (asOf == null) {
242	            all = claims.list(sheetId);
243	            bound.forEach(claim -> was.put(claim.getId(), claim));
244	        } else {
245	            on = asOf;
246	            then = people.findAsOf(sheetId, person.getId(), asOf);
247	            if (then == null) {
