249	            }
250	            rates = rates.asOf(asOf);
251	            settings = settings.asOf(asOf);
252	            all = claims.listAsOf(sheetId, asOf);
253	            all.stream().filter(claim -> claim.getPersonId() == person.getId()).forEach(claim -> was.put(claim.getId(), claim));
254	        }
255	        LocalDate policy = settings.policyDate(sheetId);
256	        Rounding rounding = new Rounding(policy != null ? policy : on, all);
257	        Person whose = then;
258	        Lateness lateness = new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), on, rounding,
