264	            // The claim as it stood then (itself when taken now); null when it was not theirs then.
265	            Claim claim = was.get(live.getId());
266	            // An OPEN (or PENDING) claim dated within a hold counts in no live total unless a statement bound
267	            // it, so a statement neither counts nor binds it; one it bound before stays counted. A deferred
268	            // claim counts in no total until the sheet's today reaches its date: a statement leaves it unbound.
269	            boolean counts = claim != null && RollupService.counts(claim, then, on);
270	            BigDecimal figure = null;
271	            boolean na = false;
272	            if (counts) {
273	                figure = ClaimFigure.of(claim, rates.find(sheetId, then.gradeOn(claim.getDate()), claim.getDate()), rounding);
274	                counted++;
275	                if (figure != null) {
276	                    total = total.add(lateness.dueOf(claim, figure));
277	                }
278	                // A figure at a grade other than the one in force today, or at a rate that ended before
279	                // today, does not hang on today's grade's rate.
280	                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
281	                        || (figure != null && (!then.gradeOn(claim.getDate()).equals(then.gradeOn(on))
282	                                || rates.endsBefore(sheetId, then.gradeOn(claim.getDate()), claim.getDate(), on)));
