286	            }
287	            live.setStated(counts);
288	            live.setStatedDue(figure);
289	            live.setStatedNa(na);
290	            claims.bind(live);
291	        }
292	        boolean na = rates.find(sheetId, then.gradeOn(on), on) == null && !fixed;
293	        Statement statement = new Statement(person.getId(), on,
294	                na ? null : SettingStore.capped(total, settings.cap(sheetId)), counted);
295	        statements.add(sheetId, statement, request.user());
296	        statementOut.set(statement);
297	    }
