=== peopleimport/ValidateImport.java
/**
 * Checks every pasted line with exactly the person form's rules before anything is stored: each line
 * is name,grade,terms,contact (terms and contact may be absent or blank). A line whose name is a person's
 * name or alias on the sheet (as names are compared) updates that person, its contact free of anyone else on
 * the sheet; any other line adds, its name and contact free on the sheet (and the name on its tree) as the form
 * requires. No name (ignoring case and the spaces around it), person or contact may be given by an earlier
 * line. Blank lines are skipped; a paste with no line is refused.
 */
public class ValidateImport {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ImportRequest request,
            PersonStore store, SettingStore settings, RoleStore roles, Out<ImportInput> imported)
            throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String sheet = sheetId.trim();
        String text = request == null || request.text() == null ? "" : request.text();
        String[] lines = text.split("\\r?\\n");
        List<ImportInput.Line> people = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<Long> updated = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (line.trim().isEmpty()) {
                continue;
            }
            String[] fields = line.split(",", -1);
            if (fields.length < 2 || fields.length > 4) {
                throw new InvalidSheetException("Line " + (i + 1) + " must be name,grade,terms,contact");
            }
            try {
                PersonRequest person = PersonRules.check(new PersonRequest(fields[0], fields[1].trim(), null,
                        request.user(), null, fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : "", null));
                Person existing = store.findByName(sheet, person.name());
                if (existing == null) {
                    PersonRules.refuseTaken(sheet, person, store, settings);
                } else if (person.contact() != null
                        && store.contactTaken(sheet, person.contact(), existing.getId())) {
                    throw new DuplicateContactException(person.contact());
                }
                if (!names.add(person.name().toLowerCase(Locale.ROOT))
                        || (existing != null && !updated.add(existing.getId()))) {
                    throw new InvalidSheetException("The name " + person.name() + " is given twice");
                }
                if (person.contact() != null && !contacts.add(person.contact())) {
                    throw new InvalidSheetException("The contact " + person.contact() + " is given twice");
                }
                people.add(new ImportInput.Line(person, existing));
            } catch (InvalidSheetException e) {
                throw new InvalidSheetException("Line " + (i + 1) + ": " + e.getMessage());
            }
        }
        if (people.isEmpty()) {
            throw new InvalidSheetException("Paste at least one line of name,grade,terms,contact");
        }
        imported.set(new ImportInput(people));
    }
}
=== peopleimport/SaveImported.java
/** Applies each imported line in order. A line naming a person on the sheet updates them as the person form
 *  would — the grade recorded from the sheet's today, their terms and contact set when the line gives them —
 *  recorded as PERSON_EDITED (and its ROLLUP); any other line adds a person as the form would, recorded as
 *  PERSON_ADDED (and its ROLLUP). */
public class SaveImported {
    public void save(@PathVariable("sheetId") String sheetId, @Val ImportInput imported, PersonStore store,
            SheetStore sheets, RollupService rollups, Audit audit, Out<ImportResult> result)
            throws StalePersonException {
        String sheet = sheetId.trim();
        int added = 0;
        int updated = 0;
        for (ImportInput.Line line : imported.lines()) {
            PersonRequest request = line.request();
            Rollup before = rollups.snapshot(sheet);
            if (line.existing() != null) {
                Person person = line.existing();
                if (request.terms() != null) {
                    person.setTerms(Integer.valueOf(request.terms()));
                }
                if (request.contact() != null) {
                    person.setContact(request.contact());
                }
                PersonRules.applyGrade(person, request.grade(), null, sheets.today(sheet));
                if (!store.save(person)) {
                    throw new StalePersonException();
                }
                audit.record("PERSON_EDITED sheet=" + person.getSheetId() + " by=" + request.user() + " name="
                        + person.getName() + " grade=" + person.gradeOn(sheets.today(sheet))
                        + (person.isTermsChanged() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : "")
                        + (person.isContactChanged() ? " contact=" + (person.getContact() == null ? "" : person.getContact()) : ""));
                rollups.record(person.getSheetId(), request.user(), before);
                updated++;
                continue;
            }
            Person person = store.add(sheet, request.name(), request.grade(),
                    request.terms() == null ? null : Integer.valueOf(request.terms()), request.contact());
            audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + request.user() + " name="
                    + person.getName() + " grade=" + request.grade()
                    + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                    + (person.getContact() == null ? "" : " contact=" + person.getContact()));
            rollups.record(person.getSheetId(), request.user(), before);
            added++;
        }
        result.set(new ImportResult(added, updated));
    }
}
