/**
 * Applies the person form's and the claim form's rules to a quick add, before anything is stored:
 * the name is required (and trimmed), the amount is 0.00 or more with up to two decimals. Publishes
 * the person as it would be added (grade A) and the draft claim (the entry date while it is set, else the sheet's today, an empty note).
 */
public class ValidateQuickAdd {
    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody QuickAddRequest request,
            SettingStore settings, Out<PersonRequest> person, Out<ClaimInput> claim, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        if (request == null || request.name() == null || request.name().trim().isEmpty()) {
            throw new InvalidSheetException("A name is required");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number of 0.00 or more with up to two decimals");
        }
        person.set(new PersonRequest(request.name().trim(), "A", null, request.user(), null, null, null, null));
        claim.set(new ClaimInput(new BigDecimal(amount).setScale(2), settings.claimDate(sheetId.trim()), "",
                request.user()));
    }
}
=== plan/Plan.java
/** A person's plan: a DRAFT claim of the amount on every plan date up to the end; {@code generated} how many
 *  claims it has made so far. The plan dates are the start then every {@code every} days, or, for a monthly plan
 *  ({@code day} set, {@code every} null), {@link #dates(LocalDate)}. */
public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
        Integer day, LocalDate end, int generated) {
    /** The plan dates up to and including {@code last}, in order. A monthly plan's are its day in every month
     *  from the start's month, a day beyond the month's length falling on its last day, those before the start
     *  left out. */
    public List<LocalDate> dates(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
                dates.add(d);
            }
            return dates;
        }
        for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
            LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
            if (!d.isBefore(start) && !d.isAfter(last)) {
                dates.add(d);
            }
        }
        return dates;
    }
    /** The first {@code count} plan dates after {@code today} and on or before the end, in order. */
    public List<LocalDate> nextDates(LocalDate today, int count) {
        return dates(end).stream().filter(d -> d.isAfter(today)).limit(count).toList();
    }
}
